function r(){return new Date(Date.now()-18e6).toISOString().slice(0,10)}function o(e,t){let n=new Date(e+"T00:00:00Z");return n.setUTCDate(n.getUTCDate()+t),n.toISOString().slice(0,10)}function a(e){if(!e)return"";let t=parseInt(e.split(":")[0],10);return t===0||t===24?"12:00 AM":t<12?`${t}:00 AM`:t===12?"12:00 PM":`${t-12}:00 PM`}function i(e){return"$"+Math.round(e??0).toLocaleString("es-CO")}function s(e,t){return`https://wa.me/${(e||"").replace(/\D/g,"")}?text=${encodeURIComponent(t)}`}export{r as a,o as b,a as c,i as d,s as e};
